203: <script>
204: "use strict";
205: /* ================= CALL OF ZOMBIES: ROUND WAR =================
206:    Self-contained raycasting FPS engine. Xbox Gamepad API with
207:    CoD Zombies presets, rumble, hold-X buy. Touch + KB/Mouse.
208:    WebAudio synth SFX/music. LocalStorage profile. 4 maps, 7
209:    zombie types, 22 weapons, perks, WAR FORGE, bosses, eggs. */
210: const $=(i)=>document.getElementById(i);
211: const clamp=(v,a,b)=>v<a?a:v>b?b:v, rnd=(a,b)=>a+Math.random()*(b-a), ri=(a,b)=>Math.floor(rnd(a,b+1));
212: const TAU=Math.PI*2, angN=a=>{while(a>Math.PI)a-=TAU;while(a<-Math.PI)a+=TAU;return a;};
