843: function hitWall(x,y,r){for(let yy=Math.floor(y-r);yy<=Math.floor(y+r+0.001);yy++)for(let xx=Math.floor(x-r);xx<=Math.floor(x+r+0.001);xx++)if(isWall(xx,yy))return true;return false;}
