845: function cast(px,py,rdx,rdy){
846:   let mx=px|0,my=py|0;
847:   const dx=Math.abs(1/(rdx||1e-9)),dy=Math.abs(1/(rdy||1e-9));
848:   let xs,ys,sdx,sdy,side=0;
849:   if(rdx<0){xs=-1;sdx=(px-mx)*dx;}else{xs=1;sdx=(mx+1-px)*dx;}
850:   if(rdy<0){ys=-1;sdy=(py-my)*dy;}else{ys=1;sdy=(my+1-py)*dy;}
851:   for(let i=0;i<80;i++){
852:     if(sdx<sdy){sdx+=dx;mx+=xs;side=0;}else{sdy+=dy;my+=ys;side=1;}
853:     const g=game.map.solid[my*MW+mx];
854:     if(g>0)return{d:side===0?sdx-dx:sdy-dy,mx,my,side};
855:   }
856:   return{d:64,mx,my,side:0};
857: }
