890: function hitScan(rdx,rdy,wd,w){
891:   if(eggHitCheck(rdx,rdy,wd))return;
892:   const cands=[];
893:   for(const z of zombies){
894:     if(z.dead||z.knock>0||z.st!=='walk'&&z.st!=='attack'&&z.st!=='climb')continue;
895:     const dx=z.x-player.x,dy=z.y-player.y,t=dx*rdx+dy*rdy;
896:     if(t<=0.25||t>wd)continue;
897:     const perp=Math.abs(dx*rdy-dy*rdx);
898:     const rad=0.36*ZT[z.t].sz;
899:     if(perp<rad)cands.push({z,t,perp,head:perp<rad*0.4&&(player.ads>0.4||z.t==='stalker'?true:perp<rad*0.4)});
900:   }
901:   cands.sort((a,b)=>a.t-b.t);
902:   let left=w.pierce||1;
903:   for(const c of cands){
904:     if(left<=0)break;
905:     const fall=c.t>9?Math.max(0.35,1-(c.t-9)/26):1;
906:     const dmg=wDmg()*fall*(c.head?2.2:1);
907:     damageZombie(c.z,dmg,rdx,rdy,c.head);
908:     left--;
909:   }
910:   if(!cands.length)parts.push({x:player.x+rdx*wd,y:player.y+rdy*wd,z:rnd(.35,.65),vx:rnd(-1,1),vy:rnd(-1,1),life:0.18,c:'#ccc',s:2});
911: }
