916:     player.burstT-=dt;
917:     if(player.burstT<=0){player.burstT=0.06;player.burstLeft--;fireOne(s,w);}
918:     return;
919:   }
920:   if(!held.fire){player.ammoIn=false;return;}
921:   if(!w.auto&&player.ammoIn)return;
