923:   if(s.mag<=0){sfx('deny',{v:0.4});lowAmmoToast();player.fireT=0.35;player.ammoIn=true;if(s.res>0)startReload();return;}
924:   player.ammoIn=!w.auto;
925:   if(w.burst){player.burstLeft=Math.min(w.burst,s.mag)-1;player.burstT=0.06;fireOne(s,w);return;}
