956: function moveC(dx,dy){
957:   const r=player.crouch?0.26:0.3;
958:   if(!hitWall(player.x+dx,player.y,r))player.x+=dx;else if(!hitWall(player.x+dx*0.4,player.y,r))player.x+=dx*0.4;
959:   else if(Math.abs(dx)>small24()){/*blocked*/}
960:   if(!hitWall(player.x,player.y+dy,r))player.y+=dy;else if(!hitWall(player.x,player.y+dy*0.4,r))player.y+=dy*0.4;
