963: function updatePlayer(dt){
964:   const aiming=held.aim;
965:   player.ads+=((aiming?1:0)-player.ads)*Math.min(1,dt*11);
966:   if(held.crouch&&!player.crouch&&player.slideT<=0&&movingFast()&&player.slideCd<=0){player.slideT=0.55;player.slideCd=1.2;}
967:   if(player.slideT>0)player.slideT-=dt;
968:   if(player.slideCd>0)player.slideCd-=dt;
969:   player.crouch=held.crouch||player.slideT>0.15;
970:   let mvx=IN.mvX,mvy=IN.mvY;const l=Math.hypot(mvx,mvy);
971:   let sp=2.95;if(hasPerk('sprint'))sp+=0.55;
972:   const sprint=held.sprint&&l>0.75&&!aiming&&!player.reloading;
973:   if(sprint)sp=5.35;
974:   if(player.crouch)sp*=0.55;
975:   if(player.ads>0.5)sp*=0.66;
976:   if(l>1){mvx/=l;mvy/=l;}
977:   const fx=Math.cos(player.a),fy=Math.sin(player.a);
978:   const dx=(fx*(-mvy)-fy*mvx)*sp*dt;
979:   const dy=(fy*(-mvy)+fx*mvx)*sp*dt;
980:   moveC(player.slideT>0?dx*1.85:dx,player.slideT>0?dy*1.85:dy);
981:   player.bob+=l*sp*dt*1.75;
982:   player.a=angN(player.a+IN.look);
983:   player.pitch=clamp(pitchAcc,-70,70)*1;pitchAcc=player.pitch;
984:   tryFire(dt);
985:   player.fireT=Math.max(0,player.fireT-dt);
986:   player.kick=Math.max(0,player.kick-dt*6);
987:   if(EDGE.reload)startReload();
988:   if(player.reloading){player.reloadT-=dt;
989:     if(player.reloadT<=wRelTime()*0.6&&!player._ck){player._ck=true;sfx('clickl');}
990:     if(player.reloadT<=0){const s=curW(),take=Math.min(wMag()-s.mag,s.res);
991:       s.mag+=take;s.res-=take;player.reloading=false;player._ck=false;sfx('clikh');updateHUD();}}
992:   if(EDGE.swap&&player.slots[1-player.cur]){player.cur=1-player.cur;player.reloading=false;player.ammoIn=false;sfx('clikh');updateHUD();}
993:   if(EDGE.melee)meleeAct();
994:   if(EDGE.nade)throwNade();
995:   player.meleeT=Math.max(0,player.meleeT-dt);
996:   doInteract(dt);
997:   player.regenT+=dt;
998:   if(player.regenT>2.6&&player.hp<player.max){player.hp=Math.min(player.max,player.hp+42*dt);
999:     dmgVig(clamp(1-player.hp/player.max,0,0.55)*0.5);updateHUD();}
1000:   for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.t-=dt;
1001:     if(p.t<=0){pickups.splice(i,1);continue;}
1002:     if(Math.hypot(p.x-player.x,p.y-player.y)<1.05){
1003:       if(p.k==='ammo'){for(const s of player.slots)if(s)s.res=WEAPONS[s.w].res;toast('+ FULL RESERVE AMMO');sfx('buy');}
1004:       else if(p.k==='pts'){givePoints(p.v);pop('+'+p.v);sfx('buy');}
1005:       else if(p.k==='gun'){takePickupGun(p.v);}
1006:       pickups.splice(i,1);updateHUD();
1007:     }
1008:   }
1009: }
