1029:   for(const w of M.buys){const d=Math.hypot(w.x-player.x,w.y-player.y);if(d<1.9&&d<bd){bd=d;best={k:'buy',o:w};}}
1030:   for(const w of M.winW){const d=Math.hypot(w.x-player.x,w.y-player.y);if(d<1.75&&d<bd){bd=d;best={k:'repair',o:w};}}
1031:   for(const p of M.perksA){const d=Math.hypot(p.x-player.x,p.y-player.y);if(d<1.9&&d<bd){bd=d;best={k:'perk',o:p};}}
1032:   {const d=Math.hypot(M.forge.x-player.x,M.forge.y-player.y);if(d<2&&d<bd){bd=d;best={k:'forge'};}}
1033:   {const d=Math.hypot(M.box.x-player.x,M.box.y-player.y);if(d<2.05&&d<bd){bd=d;best={k:'box'};}}
1034:   for(const d of M.doorsA){if(d.open)continue;const dd=Math.hypot(d.px-player.x,d.py-player.y);if(dd<2&&dd<bd){bd=dd;best={k:'door',o:d};}}
1035:   for(const g of M.eggsA){if(!g.dead){const gd=Math.hypot(g.x-player.x,g.y-player.y);if(gd<8&&gd<bd+4){best=best||{k:'egg',o:g};}}}
1036:   {const d=Math.hypot(M.radio.x-player.x,M.radio.y-player.y);if(d<1.8&&d<bd){bd=d;best={k:'radio'};}}
1037:   return best;
1038: }
