1174: function roundLogic(dt){
1175:   if(game.phase==='idle'){game.phaseT-=dt;if(game.phaseT<=0)startRound(1);return;}
1176:   if(game.phase==='intermission'){
1177:     game.phaseT-=dt;
1178:     if(game.phaseT<=0)startRound(game.round+1);
1179:     return;
1180:   }
1181:   const alive=zombies.filter(z=>!z.dead).length;
1182:   const cap=Math.min(10+game.round,26);
1183:   if(game.toSpawn>0){
1184:     game.spawnT-=dt;
1185:     if(game.spawnT<=0&&alive<cap){
1186:       let type=pickType(game.round);
1187:       if(game.phase==='boss')type=Math.random()<0.6?'walker':'runner';
1188:       if(game.event==='FRENZY'&&Math.random()<0.5)type='runner';
1189:       if(game.event==='GAS DRAG'&&Math.random()<0.3)type='exploder';
1190:       if(game.event==='NIGHTMARE'&&Math.random()<0.3)type='armored';
1191:       spawnZombie(type);game.toSpawn--;
1192:       game.spawnT=Math.max(0.4,2.1-game.round*0.07);
1193:     }
1194:   }
1195:   if(game.round%10===0&&game.phase==='active'&&!nemesis&&!game.bossDone){
1196:     game.bossDone=true;spawnBoss();
1197:   }
1198:   if(game.phase==='boss'&&nemesis&&nemesis.dead){
1199:     nemesis=null;game.phase='active';$('botC').style.display='none';musicLevel(game.musicL);
1200:   }
1201:   if(game.bossDone&&!nemesis&&game.toSpawn<=0&&zombies.every(z=>z.dead)){
1202:     game.bossDone=false;
1203:     game.phase='intermission';game.phaseT=6;player.hp=Math.min(player.max,player.hp+player.max*0.35);
1204:     player.lastUsed=false;showBanner('ROUND '+game.round+' CLEARED','BOSS SLAIN — +2500 PTS');givePoints(1000);
1205:     sfx('buy');updateHUD();
1206:   }
1207:   if(game.phase==='active'&&game.toSpawn<=0&&zombies.every(z=>z.dead)){
1208:     game.phase='intermission';game.phaseT=6.5;
1209:     player.hp=Math.min(player.max,player.hp+pa40());player.lastUsed=false;
1210:     showBanner('ROUND '+game.round+' CLEARED','NEXT WAVE...');
1211:     updateHUD();sfx('buy');
1212:   }
1213: }
