1346:   g2.addColorStop(0,M.flr[0]);g2.addColorStop(1,M.flr[1]);
1347:   ctx.fillStyle=g2;ctx.fillRect(0,Math.max(0,horizon|0),RW,RH);
1348:   // walls
1349:   for(let x=0;x<RW;x++){
1350:     const cam=2*x/RW-1;
