1357:     const tex=mat>=2?(mat===2+M.doors.findIndex(dd=>!dd.open||dd.open)&&0)||texDoorFor(M,mat):(mat===0?M.tex[1]:M.tex[(h.mx*7+h.my*13)%3]);
1358:     const wallX=h.side===0?(p.y+d*rdy):(p.x+d*rdx);
1359:     let tx=Math.floor((wallX-Math.floor(wallX))*64);
1360:     if((h.side===0&&rdx>0)||(h.side===1&&rdy<0))tx=63-tx;
1361:     try{ctx.drawImage(tex,clamp(tex,0,63)>=0?clamp(tx,0,63):0,0,1,64,x,y0,1,wh);}catch(e){}
1362:     const sh=clamp(d/(envDist()),0,0.86)+ (h.side===1?0.07:0);
1363:     ctx.fillStyle='rgba('+M.tint+','+sh.toFixed(2)+')';
1364:     ctx.fillRect(x,y0,1,wh+1);
