678: function computeFlow(){
679:   flowArr=flowArr||new Int16Array(MW*MH);
680:   flowArr.fill(32000);
681:   const q=new Int16Array(MW*MH);let h=0,t=0;
682:   const px=player.x|0,py=player.y|0;
683:   if(!openCell(px,py))return;
684:   flowArr[py*MW+px]=0;q[t++]=py*MW+px;
685:   while(h<t){const c=q[h++],cx=c%MW,cy=(c/MW)|0,d=flowArr[c];
686:     if(d>120)break;
687:     for(const[nx,ny]of[[cx+1,cy],[cx-1,cy],[cx,cy+1],[cx,cy-1]]){
688:       if(nx<0||ny<0||nx>=MW||ny>=MH)continue;
689:       const g=game.map.solid[ny*MW+nx];if(g>0&&g<2)continue;
690:       const i=ny*MW+nx;if(flowArr[i]>d+1){flowArr[i]=d+1;q[t++]=i;}}}
691: }
